ibrary.php?detail=1&track='.$t['id'].'#cue-points');}if($action==='edit'){foreach(['id','version','revision']as$k)if(!is_string($_POST[$k]??null))throw new InvalidArgumentException('Ugyldig låtreferanse.');if(!preg_match('/^[0-9]{1,8}$/D',$_POST['revision']))throw new InvalidArgumentException('Ugyldig revisjon.');$t=music_library_edit($_POST['id'],$_POST['version'],(int)$_POST['revision'],$_POST,$user,$_POST['csrf'],$_SESSION['csrf']);$_SESSION['music_library_results']=[['name'=>'Valgt låt','message'=>'Opplysninger og egne merkelapper er lagret. Originalfilen er uendret.']];redirect('/music-library.php?detail=1&track='.$t['id']);}if($action==='delete'){foreach(['id','version','revision']as$k)if(!is_string($_POST[$k]??null))throw new InvalidArgumentException('Ugyldig låtreferanse.');if(!preg_match('/^[0-9]{1,8}$/D',$_POST['revision']))throw new InvalidArgumentException('Ugyldig revisjon.');$r=music_library_delete($_POST['id'],$_POST['version'],(int)$_POST['revision'],$user,$_POST['csrf'],$_SESSION['csrf'],($_POST['confirm_delete']??null)==='yes');$_SESSION['music_library_results']=[['name'=>'Valgt låt','message'=>$r['fileDeleted']?'Låten er slettet fra biblioteket og originalfilen er fjernet fra serveren.':'Låten er fjernet fra biblioteket, men den private filresten må ryddes av administrator. Ikke regn slettingen som fullført.']];redirect('/music-library.php');}if($action==='assess'){foreach(['id','version','revision']as$k)if(!is_string($_POST[$k]??null))throw new InvalidArgumentException('Ugyldig låtreferanse.');if(!preg_match('/^[0-9]{1,8}$/D',$_POST['revision']))throw new InvalidArgumentException('Ugyldig revisjon.');$t=music_library_producer_save($config,$_POST['id'],$_POST['version'],(int)$_POST['revision'],$user,$_POST['csrf'],$_SESSION['csrf']);$_SESSION['music_library_results']=[['name'=>$t['originalName'],'message'=>'Musikkprodusentens forslag er lagret. Låten er ikke godkjent for rotasjon.']];redirect('/music-library.php?detail=1&track='.$t['id']);}if($action==='prepare'){
      foreach(['id','version','revision']as$k)if(!is_string($_POST[$k]??null))throw new InvalidArgumentException('Ugyldig klargjøring.');if(!preg_match('/^[0-9]{1,8}$/D',$_POST['revision']))throw new InvalidArgumentException('Ugyldig versjon.');
      $t=music_library_prepare($_POST['id'],$_POST['version'],(int)$_POST['revision'],$user,$_POST['csrf'],$_SESSION['csrf']);$_SESSION['music_library_results']=[['name'=>$t['originalName'],'message'=>'Filopplysninger og varighet er lest. Nettidentifisering og tagging er neste trinn.']];redirect('/music-library.php?detail=1&track='.$t['id']);
    }if($action!=='upload')throw new InvalidArgumentException('Ukjent handling.');$files=$_FILES['tracks']??null;if(!is_array($files)||!is_array($files['name']??null)||count($files['name'])<1||count($files['name'])>10)throw new InvalidArgumentException('Velg mellom én og ti MP3-filer.');
      $total=0;foreach(['tmp_name','size','error']as$k)if(!is_array($files[$k]??null)||array_keys($files[$k])!==array_keys($files['name']))throw new InvalidArgumentException('Ugyldig opplasting.');
      foreach($files['size']as$n){if(!is_int($n)||$n<0)throw new InvalidArgumentException('Ugyldig filstørrelse.');$total+=$n;}if($total>64*1024*1024)throw new InvalidArgumentException('Velg færre filer: maksimalt 64 MiB per opplasting.');
      foreach($files['name']as$i=>$name){try{$r=music_library_upload(['name'=>$name,'tmp_name'=>$files['tmp_name'][$i],'size'=>$files['size'][$i],'error'=>$files['error'][$i]],$user,$_POST['csrf'],$_SESSION['csrf']);$message=$r['duplicate']?'Finnes allerede – ingen ny kopi.':'Original lagret.';if(!$r['duplicate']){try{$prepared=music_library_prepare($r['track']['id'],$r['track']['sha256'],0,$user,$_POST['csrf'],$_SESSION['csrf']);$possible=music_library_possible_duplicates($prepared,music_library_read());if($possible)$message.=' Mulig duplikat: artist, tittel og varighet samsvarer med '.count($possible).' eksisterende låt(er). Begge beholdes for din vurdering.';$message.=' Filopplysninger og tilgjengelige tags er klargjort automatisk.';}catch(Throwable){error_log('Studio automatic music preparation failed');$message.=' Automatisk klargjøring må prøves igjen. Originalen er bevart.';}}if(!$r['duplicate']&&($_POST['audio_auto']??null)==='yes'){try{music_audio_enqueue($r['track']['id'],$r['track']['sha256'],$user,$_POST['csrf'],$_SESSION['csrf']);$_SESSION['music_audio_queue_autostart']=true;$message.=' Musikkanalysen starter i køen.';}catch(Throwable){$message.=' Analysekøen må startes på nytt fra låtdetaljene.';}}$results[]=['name'=>$name,'message'=>$message];}catch(InvalidArgumentException $e){$results[]=['name'=>is_string($name)?$name:'Fil','message'=>$e->getMessage()];}catch(Throwable $e){error_log('Studio music upload failed');$results[]=['name'=>is_string($name)?$name:'Fil','message'=>'Kunne ikke lagre filen. Kontroller biblioteket før du prøver igjen.'];}}
      $_SESSION['music_library_results']=$results;redirect('/music-library.php');
    }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable){error_log('Studio music preparation failed');$error=($action??'')==='delete'?'Slettingen kunne ikke fullføres. Kontroller biblioteket før nytt forsøk.':'Klargjøringen kunne ikke fullføres. Original og eksisterende opplysninger er bevart.';}
}else{$results=$_SESSION['music_library_results']??[];unset($_SESSION['music_library_results']);}
$available=class_exists('finfo');if(!$available)$error='Filtypekontroll mangler på serveren. Opplasting er sperret.';try{$tracks=music_library_read();}catch(Throwable $e){$available=false;$error='Biblioteket kunne ikke leses. Opplasting er sperret til det er avklart.';}
$selected=null;$requested=$_GET['track']??null;if($requested!==null&&(!is_string($requested)||!preg_match('/^[a-f0-9]{32}$/D',$requested)))$error='Ugyldig låtreferanse.';else{foreach($tracks as$t)if($requested===null||$t['id']===$requested){$selected=$t;break;}if($requested!==null&&!$selected)$error='Låten finnes ikke i biblioteket.';}
